// setfsuid(uid_t fsuid)
// Sets the Filesystem User ID (FSUID).

uid_t target_uid = 1000; // Example target UID

// To set an arbitrary UID, requires CAP_SETUID capability.
// Otherwise, fsuid must match RUID, EUID, or SUID.

int ret = setfsuid(target_uid);

if (ret == 0) {
    /* Success: FSUID updated for FS checks */
} else {
    // EPERM if insufficient privileges
    // EINVAL if UID is invalid

    // Example: Resetting FSUID to match EUID (always permitted)
    setfsuid(geteuid());
}

// Related: setfsgid(), getfsuid()
